using Microsoft.Extensions.Configuration;
using TUnit.Assertions;

namespace AutoApprover.Worker.Tests.UnitTests;

[TestFixture]
public class DecisionEngineTests
{
    private static IConfiguration CreateConfiguration(string renovateCreator = "renovate")
    {
        return new ConfigurationBuilder()
            .AddInMemoryCollection(new[]
            {
                new KeyValuePair<string, string?>("AdopSettings:RenovatePrCreator", renovateCreator)
            })
            .Build();
    }

    [Test]
    public async Task Evaluate_KeinPRGefunden_RueckgabeSkipped()
    {
        // Arrange
        var engine = new DecisionEngine(CreateConfiguration(), TestLogger.Create<DecisionEngine>());
        var check = new PendingCheck(
            Id: 1,
            EnvironmentName: "anwendung-a-prod",
            ProjectName: "AppA",
            PipelineName: "main-ci",
            RunId: 42,
            RepositoryId: "repo-1",
            SourceCommitId: "abc123",
            SourceBranch: "refs/heads/main",
            DefinitionName: "main-ci");

        // Act
        var result = engine.Evaluate(check, prInfo: null);

        // Assert
        await Assert.That(result.ShouldApprove).IsFalse();
        await Assert.That(result.Reason).Contains("Kein zugehöriger Pull-Request");
        await Assert.That(result.ChangeType).IsEqualTo("none");
    }

    [Test]
    public async Task Evaluate_PRerstellerNichtRenovate_RueckgabeSkipped()
    {
        // Arrange
        var engine = new DecisionEngine(CreateConfiguration("renovate"), TestLogger.Create<DecisionEngine>());
        var check = new PendingCheck(
            Id: 1, EnvironmentName: "anwendung-a-prod", ProjectName: "AppA",
            PipelineName: "main-ci", RunId: 42, RepositoryId: "repo-1",
            SourceCommitId: "abc123", SourceBranch: "refs/heads/main", DefinitionName: "main-ci");

        var pr = new PullRequestInfo(
            Id: 7, Title: "Update something",
            CreatorDisplayName: "Max Mustermann",
            CreatorUniqueName: "max@company.com",
            SourceBranch: "refs/heads/feature/update",
            TargetBranch: "refs/heads/main",
            ChangedFilePaths: ["Dockerfile"]);

        // Act
        var result = engine.Evaluate(check, pr);

        // Assert
        await Assert.That(result.ShouldApprove).IsFalse();
        await Assert.That(result.Reason).Contains("ist nicht der konfigurierte Renovate-Bot");
        await Assert.That(result.ChangeType).IsEqualTo("none");
        await Assert.That(result.PullRequestId).IsEqualTo(7);
    }

    [Test]
    public async Task Evaluate_PRerstellerRenovateNurDockerfileGeändert_RueckgabeApproveDockerfileDigest()
    {
        // Arrange
        var engine = new DecisionEngine(CreateConfiguration(), TestLogger.Create<DecisionEngine>());
