        var pr = new PullRequestInfo(
            Id: 7, Title: "Update docker base image",
            CreatorDisplayName: "renovate",
            CreatorUniqueName: "renovate[bot]",
            SourceBranch: "refs/heads/renovate/docker-update",
            TargetBranch: "refs/heads/main",
            ChangedFilePaths: ["Dockerfile"]);

        // Act
        var result = engine.Evaluate(check, pr);

        // Assert
        await Assert.That(result.ShouldApprove).IsTrue();
        await Assert.That(result.ChangeType).IsEqualTo("dockerfile_digest");
        await Assert.That(result.Reason).Contains("renovate");
    }

    [Test]
    public async Task Evaluate_PRerstellerRenovateNurCsprojGeändert_RueckgabeApprovePatch()
    {
