        var pr = new PullRequestInfo(
            Id: 8, Title: "Bump NuGet package",
            CreatorDisplayName: "renovate",
            CreatorUniqueName: "renovate[bot]",
            SourceBranch: "refs/heads/renovate/nuget",
            TargetBranch: "refs/heads/main",
            ChangedFilePaths: ["AppA.csproj"]);

        // Act
        var result = engine.Evaluate(check, pr);

        // Assert
        await Assert.That(result.ShouldApprove).IsTrue();
        await Assert.That(result.ChangeType).IsEqualTo("patch");
    }

    [Test]
    public async Task Evaluate_PRerstellerRenovateCsDateiGeändert_RueckgabeSkipped()
    {
        // Arrange
        var engine = new DecisionEngine(CreateConfiguration(), TestLogger.Create<DecisionEngine>());
        var check = new PendingCheck(
            Id: 1, EnvironmentName: "anwendung-a-prod", ProjectName: "AppA",
            PipelineName: "main-ci", RunId: 44, RepositoryId: "repo-1",
            SourceCommitId: "ghi789", SourceBranch: "refs/heads/main", DefinitionName: "main-ci");

        var pr = new PullRequestInfo(
            Id: 9, Title: "Fix bug",
            CreatorDisplayName: "renovate",
            CreatorUniqueName: "renovate[bot]",
