        var pr = new PullRequestInfo(
            Id: 10, Title: "Major update to .NET 9",
            CreatorDisplayName: "renovate",
            CreatorUniqueName: "renovate[bot]",
            SourceBranch: "refs/heads/renovate/major",
            TargetBranch: "refs/heads/main",
            ChangedFilePaths: ["AppA.csproj"]);

        // Act
        var result = engine.Evaluate(check, pr);

        // Assert
        await Assert.That(result.ShouldApprove).IsFalse();
        await Assert.That(result.Reason).Contains("Major-Upgrade");
        await Assert.That(result.ChangeType).IsEqualTo("none");
    }

    [Test]
    public async Task Evaluate_DockerfileUndCsDateiGemischt_RueckgabeSkipped()
    {
        // Arrange
        var engine = new DecisionEngine(CreateConfiguration(), TestLogger.Create<DecisionEngine>());
        var check = new PendingCheck(
            Id: 1, EnvironmentName: "anwendung-a-prod", ProjectName: "AppA",
            PipelineName: "main-ci", RunId: 46, RepositoryId: "repo-1",
            SourceCommitId: "mno345", SourceBranch: "refs/heads/main", DefinitionName: "main-ci");

        var pr = new PullRequestInfo(
            Id: 11, Title: "Update docker and fix code",
            CreatorDisplayName: "renovate",
            CreatorUniqueName: "renovate[bot]",
            SourceBranch: "refs/heads/renovate/mixed",
            TargetBranch: "refs/heads/main",
            ChangedFilePaths: ["Dockerfile", "Controllers/HomeController.cs"]);

        // Act
        var result = engine.Evaluate(check, pr);

        // Assert
        await Assert.That(result.ShouldApprove).IsFalse();
        await Assert.That(result.Reason).Contains("Nicht erlaubte Dateien");
    }
}

