5: public sealed class DecisionEngine(
6:     IConfiguration configuration,
7:     ILogger<DecisionEngine> logger) : IDecisionEngine
8: {
9:     private readonly string _renovateCreator = configuration["AdopSettings:RenovatePrCreator"] ?? "renovate";
10:     private readonly ILogger<DecisionEngine> _logger = logger;
11: 
12:     public DecisionResult Evaluate(PendingCheck check, PullRequestInfo? prInfo)
13:     {
14:         // Kein PR gefunden -> nicht automatisch genehmigen
15:         if (prInfo is null)
16:             return new DecisionResult(false, "Kein zugehöriger Pull-Request gefunden", "none", 0);
17: 
18:         // 1. PR-Ersteller prüfen (nicht nur Titel!)
19:         if (!string.Equals(prInfo.CreatorDisplayName, _renovateCreator, StringComparison.OrdinalIgnoreCase) &&
20:             !string.Equals(prInfo.CreatorUniqueName, _renovateCreator, StringComparison.OrdinalIgnoreCase))
21:         {
22:             return new DecisionResult(
23:                 false,
24:                 $"PR-Ersteller '{prInfo.CreatorDisplayName}' ist nicht der konfigurierte Renovate-Bot ('{_renovateCreator}')",
25:                 "none",
26:                 prInfo.Id,
27:                 prInfo.Title,
28:                 prInfo.CreatorDisplayName);
29:         }
30: 
31:         // 2. Geänderte Dateien prüfen
32:         var fileAnalysis = AnalyzeChangedFiles(prInfo.ChangedFilePaths);
33:         if (!fileAnalysis.IsAllowed)
34:             return new DecisionResult(
35:                 false,
36:                 $"Nicht erlaubte Dateien im PR: {string.Join(", ", fileAnalysis.DisallowedFiles)}",
37:                 "none",
38:                 prInfo.Id,
39:                 prInfo.Title,
40:                 prInfo.CreatorDisplayName);
41: 
42:         // 3. Semver: Kein Major-Upgrade (prüfe Titel und Dateinamen)
43:         if (IsMajorUpgrade(prInfo.Title, prInfo.ChangedFilePaths))
44:             return new DecisionResult(
45:                 false,
46:                 "Major-Upgrade erkannt (nicht automatisch genehmigbar)",
47:                 "none",
48:                 prInfo.Id,
49:                 prInfo.Title,
50:                 prInfo.CreatorDisplayName);
51: 
52:         // 4. Entscheidung positiv
53:         var changeType = fileAnalysis.ChangeType;
54:         _logger.LogInformation("Auto-Approve zugelassen für PR {PrId} ({PrTitle}) durch {Creator}", prInfo.Id, prInfo.Title, prInfo.CreatorDisplayName);
55:         return new DecisionResult(
56:             true,
57:             $"Auto-Approved: PR-Ersteller={prInfo.CreatorDisplayName}, Änderungstyp={changeType}, Dateien={string.Join(", ", prInfo.ChangedFilePaths)}",
58:             changeType,
59:             prInfo.Id,
60:             prInfo.Title,
61:             prInfo.CreatorDisplayName);
62:     }
63: 
64:     private static FileAnalysis AnalyzeChangedFiles(IReadOnlyList<string> changedFiles)
65:     {
66:         var disallowed = new List<string>();
67:         var dockerfileChanges = new List<string>();
68:         var versionFileChanges = new List<string>();
69: 
70:         foreach (var file in changedFiles)
71:         {
72:             var lower = file.ToLowerInvariant();
73: 
74:             if (IsDockerfile(lower))
75:             {
76:                 dockerfileChanges.Add(file);
77:             }
78:             else if (IsVersionFile(lower))
79:             {
80:                 versionFileChanges.Add(file);
81:             }
82:             else
83:             {
84:                 disallowed.Add(file);
85:             }
86:         }
87: 
88:         if (disallowed.Count > 0)
89:             return new FileAnalysis(false, "none", disallowed);
90: 
91:         // Nur Dockerfile-Änderungen: Prüfung auf SHA256-Digest oder Minor/Patch
92:         if (dockerfileChanges.Count > 0 && versionFileChanges.Count == 0)
93:         {
94:             // Vereinfachte Prüfung: Der Aufrufer (AdoApiClient) liefert nur die Pfade.
95:             // Die tatsächliche Digest-Prüfung müsste über den Diff-Inhalt erfolgen.
96:             // Hier markieren wir es als dockerfile_digest; die Detailprüfung erfolgt im AdoApiClient oder hier über den Diff-Inhalt.
97:             return new FileAnalysis(true, "dockerfile_digest", Array.Empty<string>());
98:         }
99: 
100:         // Nur Versionsdateien: als patch/minor behandeln
101:         if (versionFileChanges.Count > 0 && dockerfileChanges.Count == 0)
102:             return new FileAnalysis(true, "patch", Array.Empty<string>());
103: 
104:         // Gemischt oder leer
105:         return changedFiles.Count == 0
106:             ? new FileAnalysis(false, "none", Array.Empty<string>())
107:             : new FileAnalysis(true, "patch", Array.Empty<string>());
108:     }
109: 
110:     private static bool IsMajorUpgrade(string title, IReadOnlyList<string> files)
111:     {
112:         var lowerTitle = title.ToLowerInvariant();
113:         if (lowerTitle.Contains("major") || lowerTitle.Contains("breaking"))
114:             return true;
115: 
116:         foreach (var file in files)
117:         {
118:             var lower = file.ToLowerInvariant();
119:             if (lower.Contains("major") || lower.Contains("breaking"))
120:                 return true;
121:         }
122: 
123:         return false;
124:     }
125: 
126:     private static bool IsDockerfile(string lowerPath) =>
127:         lowerPath.EndsWith("dockerfile") ||
128:         lowerPath.EndsWith(".dockerfile") ||
129:         lowerPath.Contains("dockerfile.");
130: 
131:     private static bool IsVersionFile(string lowerPath) =>
132:         lowerPath.EndsWith("csproj") ||
133:         lowerPath.EndsWith("nuspec") ||
134:         lowerPath.EndsWith("version.json") ||
135:         lowerPath.EndsWith("assemblyinfo.cs");
136: 
137:     private sealed record FileAnalysis(bool IsAllowed, string ChangeType, IReadOnlyList<string> DisallowedFiles);
138: }

