            if (oldMajor != newMajor)
                return false; // Major-Wechsel nicht erlaubt

            // Wenn Digest sich geändert hat und Tags identisch sind -> erlaubt (Digest-Update)
            if (string.Equals(oldTag, newTag, StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(oldDigest, newDigest, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            // Wenn Tags unterschiedlich sind (aber gleiche Major) -> Minor/Patch, erlaubt
            if (!string.Equals(oldTag, newTag, StringComparison.OrdinalIgnoreCase))
                return true;

            // Alles identisch -> keine Änderung
            return false;
        }

        return false;
    }

    private static int GetMajorVersion(string tag)
    {
        // Entferne führendes 'v' falls vorhanden
        var clean = tag.StartsWith("v", StringComparison.OrdinalIgnoreCase) ? tag[1..] : tag;
        var match = Regex.Match(clean, @"^(\d+)");
        return match.Success ? int.Parse(match.Groups[1].Value) : int.MaxValue;
    }

    private static bool IsMajorUpgrade(string title, IReadOnlyList<string> files)
    {
        var lowerTitle = title.ToLowerInvariant();
        if (lowerTitle.Contains("major") || lowerTitle.Contains("breaking"))
            return true;

        foreach (var file in files)
        {
            var lower = file.ToLowerInvariant();
            if (lower.Contains("major") || lower.Contains("breaking"))
                return true;
        }

        return false;
    }

    private static bool IsDockerfile(string lowerPath) =>
        lowerPath.EndsWith("dockerfile") ||
        lowerPath.EndsWith(".dockerfile") ||
        lowerPath.Contains("dockerfile.");

    private static bool IsVersionFile(string lowerPath) =>
        lowerPath.EndsWith("csproj") ||
        lowerPath.EndsWith("nuspec") ||
        lowerPath.EndsWith("version.json") ||
        lowerPath.EndsWith("assemblyinfo.cs");

    private sealed record FileAnalysis(bool IsAllowed, string ChangeType, IReadOnlyList<string> DisallowedFiles);
}

using System.Text.Json;
using AutoApprover.Worker.Models;

namespace AutoApprover.Worker.Services;

public sealed class TeamsNotifier(
    string webhookUrl,
    ILogger<TeamsNotifier> logger) : ITeamsNotifier
{
    private static readonly HttpClient HttpClient = new();
    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

    public async Task NotifyAsync(DecisionResult decision)
    {
        if (string.IsNullOrEmpty(webhookUrl))
            return;

        var color = decision.ShouldApprove ? "00FF00" : "FF0000";
        var title = decision.ShouldApprove ? "✅ Auto-Approver: Release genehmigt" : "⏭️ Auto-Approver: Release übersprungen";

        var card = new
        {
            type = "MessageCard",
            summary = title,
            themeColor = color,
            title = title,
            sections = new[]
            {
                new
                {
                    facts = new[]
                    {
                        new { name = "Entscheidung", value = (object?)decision.Decision ?? "–" },
                        new { name = "Grund", value = (object?)decision.Reason ?? "–" },
                        new { name = "Änderungstyp", value = (object?)decision.ChangeType ?? "–" },
                        new { name = "PR-ID", value = (object?)(decision.PullRequestId == 0 ? "–" : decision.PullRequestId.ToString(CultureInfo.InvariantCulture)) ?? "–" },
                        new { name = "PR-Titel", value = (object?)(decision.PullRequestTitle ?? "–") ?? "–" },
                        new { name = "PR-Ersteller", value = (object?)(decision.PullRequestCreator ?? "–") ?? "–" },
                        new { name = "Umgebung", value = (object?)(decision.EnvironmentName ?? "–") ?? "–" },
                        new { name = "Projekt", value = (object?)(decision.ProjectName ?? "–") ?? "–" },
                        new { name = "Zeit", value = (object?)DateTimeOffset.UtcNow.ToString("yyyy-MM-dd HH:mm:ss UTC", CultureInfo.InvariantCulture) ?? "–" }
                    }
                }
            }
        };

        var json = JsonSerializer.Serialize(card, JsonOptions);
        using var content = new StringContent(json, System.Text.Encoding.UTF8, "application/json");

        try
        {
            var response = await HttpClient.PostAsync(webhookUrl, content);
            response.EnsureSuccessStatusCode();
            logger.LogInformation("Teams-Benachrichtigung gesendet (Entscheidung: {Decision})", decision.Decision);
        }
        catch (Exception ex)
        {
            // Teams-Benachrichtigung darf den Worker nicht abstürzen lassen
            logger.LogWarning(ex, "Fehler beim Senden der Teams-Nachricht: {Message}", ex.Message);
        }
    }
}

