Das ist kompliziert. Die einfachste Lösung ohne Interface-Änderung: Ich kombiniere die beiden Aufrufe in einen, indem ich eine neue private Methode `GetPullRequestDiffAsync` erstelle, die einen Record mit beidem zurückgibt, und dann in `GetPullRequestForCommitAsync` nur diese eine Methode aufrufe.

Lass mich das so machen:

```csharp
private sealed record DiffInfo(IReadOnlyList<string> ChangedFiles, IReadOnlyDictionary<string, string> DockerfileDiffs);

private async Task<DiffInfo> GetPullRequestDiffAsync(string repositoryId, int pullRequestId, CancellationToken ct)
{
    var url = $"_apis/git/repositories/{repositoryId}/pullrequests/{pullRequestId}/diffs/commits?api-version={ApiVersion}";

    using var response = await httpClient.GetAsync(url, ct);
    if (!response.IsSuccessStatusCode)
        return new DiffInfo(Array.Empty<string>(), new Dictionary<string, string>());

    var json = await response.Content.ReadAsStringAsync(ct);
    var doc = JsonDocument.Parse(json);

    var files = new List<string>();
    var diffs = new Dictionary<string, string>();

    foreach (var change in doc.RootElement.GetProperty("changes").EnumerateArray())
    {
        if (!change.TryGetProperty("item", out var item) ||
            !item.TryGetProperty("path", out var path))
        {
            continue;
        }

        var filePath = path.GetString() ?? string.Empty;
        files.Add(filePath);

        if (!IsDockerfile(filePath.ToLowerInvariant()))
            continue;

        var sb = new System.Text.StringBuilder();

        if (change.TryGetProperty("originalContent", out var original) &&
            original.TryGetProperty("content", out var originalContent))
        {
            sb.AppendLine("=== ALT ===");
            sb.AppendLine(originalContent.GetString() ?? string.Empty);
        }

        if (change.TryGetProperty("newContent", out var neu) &&
            neu.TryGetProperty("content", out var newContent))
        {
            sb.AppendLine("=== NEU ===");
            sb.AppendLine(newContent.GetString() ?? string.Empty);
        }

        if (sb.Length > 0)
            diffs[filePath] = sb.ToString();
    }

    return new DiffInfo(files, diffs);
}
```

