114:     private async Task<(IReadOnlyList<string> ChangedFiles, IReadOnlyDictionary<string, string> DockerfileDiffs)> GetPullRequestDiffAsync(
115:         string repositoryId,
116:         int pullRequestId,
117:         CancellationToken ct)
118:     {
119:         var url = $"_apis/git/repositories/{repositoryId}/pullrequests/{pullRequestId}/diffs/commits?api-version={ApiVersion}";
120: 
121:         using var response = await httpClient.GetAsync(new Uri(url), ct).ConfigureAwait(false);
122:         if (!response.IsSuccessStatusCode)
123:         {
124:             return (Array.Empty<string>(), new Dictionary<string, string>());
125:         }
126: 
127:         var json = await response.Content.ReadAsStringAsync(ct).ConfigureAwait(false);
128:         var doc = JsonDocument.Parse(json);
129: 
130:         var files = new List<string>();
131:         var diffs = new Dictionary<string, string>();
132:         foreach (var change in doc.RootElement.GetProperty("changes").EnumerateArray())
133:         {
134:             if (!change.TryGetProperty("item", out var item) ||
135:                 !item.TryGetProperty("path", out var path))
136:             {
137:                 continue;
138:             }
139: 
140:             var filePath = path.GetString() ?? string.Empty;
141:             files.Add(filePath);
142: 
143:             if (!IsDockerfile(filePath.ToUpperInvariant()))
144:             {
145:                 continue;
146:             }
147: 
148:             // Versuche, alten und neuen Inhalt zu extrahieren (je nach ADO Server Version verfügbar)
149:             var sb = new System.Text.StringBuilder();
150: 
151:             if (change.TryGetProperty("originalContent", out var original) &&
152:                 original.TryGetProperty("content", out var originalContent))
153:             {
154:                 sb.AppendLine("=== ALT ===");
155:                 sb.AppendLine(originalContent.GetString() ?? string.Empty);
156:             }
157: 
158:             if (change.TryGetProperty("newContent", out var neu) &&
159:                 neu.TryGetProperty("content", out var newContent))
160:             {
161:                 sb.AppendLine("=== NEU ===");
162:                 sb.AppendLine(newContent.GetString() ?? string.Empty);
163:             }
164: 
165:             if (sb.Length > 0)
166:             {
167:                 diffs[filePath] = sb.ToString();
168:             }
169:         }
170: 
171:         return (files, diffs);
172:     }
173: 
174:     private static bool IsDockerfile(string upperPath) =>
175:         upperPath.EndsWith("DOCKERFILE", StringComparison.Ordinal) ||
176:         upperPath.EndsWith(".DOCKERFILE", StringComparison.Ordinal) ||
177:         upperPath.Contains("DOCKERFILE.", StringComparison.Ordinal);
178: }

